<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class SalesReturn extends Model{protected $fillable=['business_id','branch_id','customer_id','sales_invoice_id','user_id','return_number','return_date','total_amount','due_reduction','refund_amount','refund_method','reason'];protected function casts():array{return['return_date'=>'date','total_amount'=>'decimal:2','due_reduction'=>'decimal:2','refund_amount'=>'decimal:2'];}public function invoice(){return $this->belongsTo(SalesInvoice::class,'sales_invoice_id');}public function customer(){return $this->belongsTo(Customer::class);}public function items(){return $this->hasMany(SalesReturnItem::class);}}
